import{_ as t,o,c,ak as d}from"./chunks/framework.Bh2SsxPX.js";const k=JSON.parse('{"title":"无限数量的物品栈","description":"","frontmatter":{},"headers":[],"relativePath":"posts/docs/util/stack/index.md","filePath":"posts/docs/util/stack/index.md","lastUpdated":1777878001000}'),i={name:"posts/docs/util/stack/index.md"};function l(a,e,s,n,r,m){return o(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="无限数量的物品栈" tabindex="-1">无限数量的物品栈 <a class="header-anchor" href="#无限数量的物品栈" aria-label="Permalink to “无限数量的物品栈”">​</a></h1><p><code>dev.anvilcraft.lib.v2.util.stack.UnlimitedItemStack</code> 是支持无限数量的物品栈实现（数量可超过 64），适用于配方成本、大型物品容器等。</p><p><strong>构造方式</strong>：</p><ul><li><code>new UnlimitedItemStack(ItemStack, int count)</code> – 从原版 ItemStack 复制物品与组件，仅保留一个数量的栈，count 单独存储</li><li>提供 <code>CODEC</code>, <code>MAP_CODEC</code>, <code>STREAM_CODEC</code> 用于序列化</li><li><code>serializeNBT</code> / <code>deserializeNBT</code> – NBT 读写</li><li><code>parse(HolderLookup.Provider, Tag)</code> – 解析为 Optional</li></ul><p><strong>常用方法</strong>：</p><ul><li><code>isEmpty()</code>, <code>copy()</code>, <code>copyWithCount(int)</code></li><li><code>grow(int)</code> – 增加数量</li><li><code>splitUnlimited(int)</code> – 切分并返回新 UnlimitedItemStack（不影响原版最大堆叠数）</li><li><code>split(int)</code> – 返回原版 ItemStack（不超过最大堆叠数），剩余数量减少</li><li><code>toStack()</code> – 生成一个可能数量 &gt; 64 的 ItemStack（不推荐直接使用）</li><li><code>toStacks()</code> – 按原版最大堆叠数分包为 <code>List&lt;ItemStack&gt;</code></li><li><code>is(Item)</code>, <code>is(TagKey&lt;Item&gt;)</code>, <code>isAny(ItemLike...)</code> – 物品匹配</li><li><code>isSameItemSameComponents(ItemStack/UnlimitedItemStack)</code> – 忽略数量比较</li><li><code>listMatches</code>, <code>hashStackList</code> – 列表比较与哈希</li></ul><p><strong>注意</strong>：<code>hashCode()</code> 和 <code>equals()</code> 基于物品、数量、组件；实现 <code>split</code> 时数量不得超过 64。</p>',7)])])}const _=t(i,[["render",l]]);export{k as __pageData,_ as default};
